import{at as e,it as t,t as n,yt as r}from"./chunks/framework.BXnsBMxG.js";var i=JSON.parse(`{"title":"Overview","description":"Start here to configure relationships in WarpDrive; links each cardinality page from one-to-none through many-to-many plus the inverses, LinksMode, and polymorphism guides.","frontmatter":{"title":"Overview","description":"Start here to configure relationships in WarpDrive; links each cardinality page from one-to-none through many-to-many plus the inverses, LinksMode, and polymorphism guides."},"headers":[],"relativePath":"guides/the-manual/relational-data/index.md","filePath":"guides/the-manual/relational-data/index.md"}`),a={name:`guides/the-manual/relational-data/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="relationships-guide" tabindex="-1">Relationships Guide <a class="header-anchor" href="#relationships-guide" aria-label="Permalink to “Relationships Guide”">​</a></h1><p>Relationships connect resources to each other: a <code>user</code> has a <code>bestFriend</code>, a <code>post</code> has many <code>comments</code>, a <code>pet</code> belongs to an <code>owner</code>. WarpDrive models every relationship as a field on a resource schema, stores its state in a relational graph, and exposes it on records as a reactive value that updates as the cache changes.</p><p>There are two kinds of relationship field, each with a legacy counterpart:</p><table tabindex="0"><thead><tr><th>Cardinality</th><th>Field kind</th><th>Value on the record</th><th>Legacy field kind</th><th>Legacy value</th></tr></thead><tbody><tr><td>one</td><td><code>resource</code></td><td>a <a href="./features/resource-relationships">relationship document</a> whose <code>data</code> is the related record or <code>null</code></td><td><code>belongsTo</code></td><td>the related record (or a promise proxy when async)</td></tr><tr><td>many</td><td><code>collection</code></td><td>a <a href="./features/collection-relationships">relationship document</a> whose <code>data</code> is a reactive array of records</td><td><code>hasMany</code></td><td>a <code>ManyArray</code> (or a promise proxy when async)</td></tr></tbody></table><p><code>resource</code> and <code>collection</code> are the field kinds to reach for in new code, and the only relationship kinds whose behavior is identical in <a href="./../schemas/resources/legacy-mode">LegacyMode</a> and <a href="./../schemas/resources/polaris-mode">PolarisMode</a>. <code>belongsTo</code> and <code>hasMany</code> remain fully supported for apps migrating from <code>@warp-drive/legacy/model</code>.</p><p>The exact rules every relationship kind follows are collected in the <a href="./spec">Relationship Specification</a>.</p><h2 id="feature-overview" tabindex="-1">Feature Overview <a class="header-anchor" href="#feature-overview" aria-label="Permalink to “Feature Overview”">​</a></h2><ul><li><a href="./features/resource-relationships">Resource Relationships</a></li><li><a href="./features/collection-relationships">Collection Relationships</a></li><li><a href="./features/links-vs-identifiers">Links vs Identifiers</a></li><li><a href="./features/sync-vs-async">Sync vs Async</a></li><li><a href="./features/inverses">Inverses</a></li><li><a href="./features/polymorphism">Polymorphism</a></li><li><a href="./../misc/links-mode">LinksMode</a> (for <code>belongsTo</code> and <code>hasMany</code>)</li><li><a href="./../experiments/pagination">Pagination</a> (experimental): load a large collection page by page as its own request instead of through a relationship</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><ul><li><a href="./configuration/one-to-none">One To None</a> (1:0)</li><li><a href="./configuration/one-to-one">One To One</a> (1:1)</li><li><a href="./configuration/one-to-many">One To Many</a> (1:N)</li><li><a href="./configuration/many-to-none">Many To None</a> (N:0)</li><li><a href="./configuration/many-to-one">Many To One</a> (N:1)</li><li><a href="./configuration/many-to-many">Many To Many</a> (N:N)</li></ul><h2 id="mutating-relationships" tabindex="-1">Mutating Relationships <a class="header-anchor" href="#mutating-relationships" aria-label="Permalink to “Mutating Relationships”">​</a></h2><ul><li><a href="./mutating/adding-removing">Adding &amp; Removing</a></li><li><a href="./mutating/saving">Saving</a></li><li><a href="./mutating/sorting-filtering">Sorting &amp; Filtering</a></li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><ul><li><a href="./spec">Relationship Specification</a></li></ul><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to “Advanced”">​</a></h2><ul><li><a href="./advanced/the-graph">Understanding &quot;the Graph&quot;</a></li><li><a href="./advanced/pagination">Pagination</a></li><li><a href="./advanced/large-collections">Large Collections</a></li><li><a href="./advanced/directionality">Directionality</a></li></ul><h1 id="misc" tabindex="-1">Misc <a class="header-anchor" href="#misc" aria-label="Permalink to “Misc”">​</a></h1><ul><li><a href="./../misc/terminology#relationships">Terminology</a></li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};